add_filter( 'woocommerce_account_downloads_columns', 'perfectpixel_hide_downloads_columns' );

function perfectpixel_hide_downloads_columns( $columns ) {
	foreach ( array_filter( array_map( 'trim', explode( ',', '{{hidden_download_columns}}' ) ) ) as $key ) {
		unset( $columns[ $key ] );
	}
	return $columns;
}
